const PREFIX = 'boids-';
const CACHE = PREFIX + 'frozen-' + VERSION;
/** Records which version this device is frozen at (written on activation). */
const MARKER = PREFIX + 'installed';

/** @param {string} path */
const absolute = (path) => new URL(path, self.location.href).href;
const MARKER_URL = absolute('./installed-version');
/** The app shell: what the start URL and in-app navigations show. */
const SHELL = absolute('./index.html');
/** The scope root, i.e. the start URL without its query string. */
const ROOT_PATH = new URL('./', self.location.href).pathname;
/** Absolute URL → expected hash. */
const HASHES = new Map(Object.entries(FILES).map(([path, hash]) => [absolute(path), hash]));

/** @param {ArrayBuffer} buffer */
async function sha256(buffer) {
  const digest = new Uint8Array(await crypto.subtle.digest('SHA-256', buffer));
  let binary = '';
  for (const byte of digest) binary += String.fromCharCode(byte);
  return btoa(binary);
}

/** @returns {Promise<string | null>} The version this device is frozen at, if any. */
async function frozenVersion() {
  if (!(await caches.has(MARKER))) return null;
  const saved = await (await caches.open(MARKER)).match(MARKER_URL);
  return saved ? saved.text() : null;
}

/**
 * The one-time download. Files that verified are kept even when another one
 * fails, so a retry only downloads what is missing.
 */
async function saveApp() {
  const cache = await caches.open(CACHE);
  const results = await Promise.allSettled(
    [...HASHES].map(async ([url, hash]) => {
      if (await cache.match(url)) return; // saved by an earlier, interrupted attempt
      const response = await fetch(url, { cache: 'reload' });
      const body = response.ok ? await response.arrayBuffer() : null;
      if (!body || (await sha256(body)) !== hash) {
        throw new Error(`${url} (HTTP ${response.status}) does not match version ${VERSION}`);
      }
      const type = response.headers.get('Content-Type');
      await cache.put(url, new Response(body, { headers: type ? { 'Content-Type': type } : {} }));
    }),
  );
  const failure = results.find((result) => result.status === 'rejected');
  if (failure) throw failure.reason;
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const frozen = await frozenVersion();
      if (frozen && frozen !== VERSION) {
        throw new Error(`Boids is frozen at version ${frozen} on this device: no updates`);
      }
      await saveApp();
      // Replacing an earlier, updating build: take over now, so it stops
      // using the network.
      if (self.registration.active) await self.skipWaiting();
    })(),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      await (await caches.open(MARKER)).put(MARKER_URL, new Response(VERSION));
      for (const key of await caches.keys()) {
        if (key.startsWith(PREFIX) && key !== CACHE && key !== MARKER) await caches.delete(key);
      }
      await self.clients.claim();
    })(),
  );
});

// Every request is answered here, from the saved copy. None reaches the network.
self.addEventListener('fetch', (event) => {
  event.respondWith(fromDevice(event.request));
});

/** Shown instead of the app if the browser deleted the saved copy (storage pressure). */
const MISSING_PAGE = `<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Boids</title><body style="margin:0;display:grid;place-items:center;min-height:100vh;background:#040d1a;color:#cde8ff;font:16px system-ui,sans-serif;text-align:center;padding:24px;box-sizing:border-box">
<p>The saved copy of Boids is missing from this device.<br>To get it back, clear this site’s data (or remove the app), then open it again while online.</p>`;

/**
 * @param {Request} request
 * @returns {Promise<Response>}
 */
async function fromDevice(request) {
  const url = new URL(request.url);
  if (request.method === 'GET' && url.origin === self.location.origin) {
    // The start URL (with or without query parameters) is the app shell.
    const key = url.pathname === ROOT_PATH ? SHELL : url.origin + url.pathname;
    const cache = await caches.open(CACHE);
    const saved = (await cache.match(key)) ?? (request.mode === 'navigate' ? await cache.match(SHELL) : undefined);
    if (saved) return saved;
    if (request.mode === 'navigate') {
      return new Response(MISSING_PAGE, { status: 503, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
    }
  }
  return Response.error();
}

self.addEventListener('message', (event) => {
  if (event.data && event.data.type === 'STATUS' && event.ports[0]) {
    event.ports[0].postMessage({ version: VERSION, files: HASHES.size });
  }
});
